import { NextResponse } from 'next/server';

const mockDatabase: Record<string, any> = {
    "12345678901": { name: "Hélio Santos", email: "helio@exemplo.com", phone: "(11) 98888-7777" },
    "98765432100": { name: "Maria Oliveira", email: "maria@cert.com.br", phone: "(21) 97777-6666" },
    "12345678000199": { name: "Delta Tecnologia LTDA", email: "contato@delta.com.br", phone: "(11) 3333-4444" },
};

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const doc = searchParams.get('doc')?.replace(/[^0-9]/g, '');

    if (!doc) return NextResponse.json({ error: "Documento não informado" }, { status: 400 });

    const customer = mockDatabase[doc];

    if (customer) {
        return NextResponse.json(customer);
    }

    return NextResponse.json({ message: "Nenhum dado prévio encontrado para este documento." }, { status: 404 });
}
